def iter_messages_in_batches(
    db,
    conv_id: str,
    batch_size: int = 500,
) -> Iterable[Tuple[str, str]]:
    """
    Iterate all messages in a conversation (oldest -> newest) in DB batches.
    """
    try:
        from app.db.crud_conversation import fetch_all_messages_in_batches
    except Exception:
        logger.debug("iter_messages_in_batches: missing helper")
        return

    offset = 0
    while True:
        try:
            batch = fetch_all_messages_in_batches(db, conv_id, limit=batch_size, offset=offset)
        except Exception:
            logger.exception("iter_messages_in_batches: failed to fetch")
            return

        if not batch:
            return

        for m in batch:
            role = getattr(m, "role", None) or (m.get("role") if isinstance(m, dict) else "user")
            content = getattr(m, "content", None) or (m.get("content") if isinstance(m, dict) else "")
            yield (str(role), str(content))

        offset += len(batch)

